// Three gates must PASS before any AI work happens. A missing/failed lookup is "unavailable", never "passed".
const input = $('Execute Workflow Trigger').first().json;
const visit = $('Fetch visit & note').first().json;
const policy = $('Fetch policy status').first().json;
const billing = $('Fetch billing context').first().json;

const errored = (o) => !o || !!o.error;
const gate = (key, label, status, detail) => (detail ? { key, label, status, detail } : { key, label, status });
const unavailable = (key, label, what) => gate(key, label, 'unavailable', `${what} did not respond, so this check could not be completed.`);

const note = visit?.note ?? {};
const complete = !errored(visit) && note.text && visit.patient?.id && visit.provider?.id;

const gates = {
  signed_note: errored(visit) ? unavailable('signed_note', 'Signed note', 'The visit/note service')
    : !complete ? gate('signed_note', 'Signed note', 'unavailable', 'The visit record is missing the note text, patient or provider.')
    : note.signed_at ? gate('signed_note', 'Signed note', 'passed')
    : gate('signed_note', 'Signed note', 'failed', 'The visit note has not been signed.'),
  active_policy: errored(policy) ? unavailable('active_policy', 'Active policy', 'The eligibility service')
    : policy.active === true ? gate('active_policy', 'Active policy', 'passed')
    : policy.active === false ? gate('active_policy', 'Active policy', 'failed', 'Insurance was not active on the date of service.')
    : gate('active_policy', 'Active policy', 'unavailable', 'The eligibility response did not state whether the policy was active.'),
  billable_event: errored(visit) ? unavailable('billable_event', 'Billable event', 'The visit/note service')
    : visit.billable?.qualifies === true ? gate('billable_event', 'Billable event', 'passed')
    : visit.billable?.qualifies === false ? gate('billable_event', 'Billable event', 'failed', visit.billable?.reason ?? 'This visit does not qualify as a billable event.')
    : gate('billable_event', 'Billable event', 'unavailable', 'The visit record did not state whether the event is billable.'),
};

const proceed = Object.values(gates).every((g) => g.status === 'passed');
return [{ json: {
  proceed, gates, input,
  visit: errored(visit) ? null : visit,
  policy: errored(policy) ? null : policy,
  billing: errored(billing) ? null : billing,
  billing_unavailable: errored(billing),
} }];

