// Maps candidate codes, VERIFIES the cited evidence against the signed note, applies payer/CMS rules,
// runs the completeness checklist and the complexity/value threshold, and assembles the draft claim.
const pre = $('Pre-flight validations').first().json;
const ex = $('AI extraction adapter').first().json;
const cat = $('Catalog lookup').first().json;
const rules = $('Payer / CMS rules').first().json;
const input = pre.input;
const visit = pre.visit;
const noteText = visit.note.text;
const runId = input.run_id;
const claimId = input.claim_id ?? ('C-' + String(visit.visit_id).replace(/^V-/, ''));
const now = new Date().toISOString();

const bad = (o) => !o || !!o.error;
const catalog = bad(cat) ? null : (cat.codes ?? {});
const reqs = bad(rules) ? null : (rules.requirements ?? {});
const checklist = bad(rules) ? [] : (rules.checklist ?? []);
const rulesetVersion = bad(rules) ? 'unavailable' : (rules.ruleset_version ?? 'unknown');
const RVU_THRESHOLD = Number($env.COMPLEXITY_RVU_THRESHOLD || 0);
const lower = noteText.toLowerCase();

// sentence index (for snapping evidence to whole sentences)
const sentences = [];
{ const re = /[^.!?]+[.!?]+|[^.!?]+$/g; let m;
  while ((m = re.exec(noteText))) { const t = m[0].trim(); if (!t) continue; const lead = m[0].length - m[0].trimStart().length; sentences.push({ start: m.index + lead, end: m.index + lead + t.length }); } }

function locate(quote) {
  if (!quote || typeof quote !== 'string' || !quote.trim()) return null;
  let idx = noteText.indexOf(quote), len = quote.length;
  if (idx < 0) {
    const pattern = quote.trim().split(/\s+/).map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('\\s+');
    const m = new RegExp(pattern, 'i').exec(noteText);
    if (!m) return null;
    idx = m.index; len = m[0].length;
  }
  const end = idx + len;
  const covered = sentences.filter((s) => s.start < end && s.end > idx);
  if (!covered.length) return { start: idx, end };
  return { start: Math.min(...covered.map((s) => s.start)), end: Math.max(...covered.map((s) => s.end)) };
}

const isEM = (c) => /^992\d\d$/.test(c);
const missingChecklist = checklist.filter((item) => !(item.terms ?? []).some((t) => lower.includes(String(t).toLowerCase())));
const billed = pre.billing?.previous_claims ?? [];

const audit = [];
const A = (event, entity, o = {}) => audit.push({
  ts: now, actor: o.actor ?? 'Coding Assistant', actor_type: o.actor_type ?? 'ai', event, entity,
  claim_id: claimId, visit_id: visit.visit_id, patient_id: visit.patient.id, code: o.code ?? null,
  previous_value: null, new_value: o.new_value ?? null, run_id: runId, version: null, metadata: o.metadata ?? {},
});

A('Signed note received', `Visit ${visit.visit_id}`, { actor: 'Workflow Engine', actor_type: 'system', metadata: { note_signed_at: String(visit.note.signed_at), mode: input.mode } });
A('Note excerpt used by AI extraction', `Visit ${visit.visit_id}`, { metadata: { characters_sent: String(noteText.length), sent_to: 'extraction adapter' } });

const candidates = [
  ...(ex.procedures ?? []).map((x) => ({ ...x, kind: 'procedure' })),
  ...(ex.diagnoses ?? []).map((x) => ({ ...x, kind: 'diagnosis' })),
];
const seen = new Set();
const codes = [];

candidates.forEach((c, i) => {
  const code = String(c.code ?? '').toUpperCase().trim();
  if (!code) return;
  if (seen.has(code)) { A('Duplicate proposal suppressed', `Code ${code}`, { code, actor: 'Workflow Engine', actor_type: 'system', metadata: { reason: 'same code proposed more than once' } }); return; }
  seen.add(code);

  const entry = catalog ? catalog[code] : undefined;
  const span = locate(c.evidence_quote);
  const mk = (status, detail) => (detail ? { key: 'documentation_requirement', label: 'Documentation requirement', status, detail } : { key: 'documentation_requirement', label: 'Documentation requirement', status });

  let doc;
  if (!span) doc = mk('failed', 'The cited evidence does not appear in the signed note.');
  else if (!catalog) doc = mk('unavailable', 'The code catalog did not respond, so the code could not be verified.');
  else if (!entry) doc = mk('failed', `Code ${code} was not found in the code catalog.`);
  else if (!reqs) doc = mk('unavailable', 'The payer/CMS rules service did not respond, so documentation requirements could not be verified.');
  else {
    const need = reqs[code]?.required_terms ?? [];
    const missing = need.filter((t) => !lower.includes(String(t).toLowerCase()));
    if (missing.length) doc = mk('failed', `Missing required documentation: ${missing.join(', ')}.`);
    else if (isEM(code) && missingChecklist.length) doc = mk('warning', `Completeness checklist is missing: ${missingChecklist.map((m) => m.label).join(', ')}.`);
    else doc = mk('passed');
  }

  const billable = { ...pre.gates.billable_event };
  if (billable.status === 'passed') {
    const dup = billed.find((b) => b.code === code && b.service_date === visit.service_date);
    if (dup) { billable.status = 'warning'; billable.detail = `Code ${code} was already billed for this date of service (claim ${dup.claim_id ?? 'unknown'}).`; }
    else if (pre.billing_unavailable) { billable.status = 'warning'; billable.detail = 'The duplicate-billing check was unavailable.'; }
  }

  const validation = [doc, { ...pre.gates.signed_note }, billable, { ...pre.gates.active_policy }];
  const high = !!entry && (entry.complexity === 'high' || (RVU_THRESHOLD > 0 && Number(entry.rvu) >= RVU_THRESHOLD));
  const confidence = Math.min(1, Math.max(0, Number(c.confidence) || 0));
  const quarantined = validation.some((g) => g.status === 'failed');
  const evidence = span
    ? { excerpt: noteText.slice(span.start, span.end).trim(), start: span.start, end: span.end }
    : { excerpt: String(c.evidence_quote ?? ''), start: 0, end: 0 };

  codes.push({
    id: `code_${runId}_${i}`, code,
    category: entry?.category ?? (c.kind === 'diagnosis' ? 'ICD-10' : 'CPT'),
    description: entry?.description ?? c.description ?? 'Description unavailable',
    confidence, complexity: high ? 'high' : 'standard',
    complexityReason: high
      ? `High-complexity level: ${entry.complexity === 'high' ? 'this code is classified as high-complexity' : `its relative value (${entry.rvu}) meets the configured threshold (${RVU_THRESHOLD})`}. Additional documentation review is required; this does not mean the code is incorrect.`
      : undefined,
    evidence, validation, decision: 'pending', quarantined,
  });

  const meta = { model_confidence: `${Math.round(confidence * 100)}%`, category: entry?.category ?? 'unknown' };
  A(c.kind === 'diagnosis' ? 'Diagnosis extracted' : 'Procedure extracted', `Code ${code}`, { code, metadata: meta });
  A('Code proposed', `Code ${code}`, { code, metadata: { ...meta, complexity: high ? 'high' : 'standard' } });
  A('Supporting evidence selected', `Code ${code}`, { code, metadata: { excerpt: `"${evidence.excerpt}"`, offset: span ? `${span.start}–${span.end}` : 'not found in note', located_in_note: String(!!span) } });
  A('Validation result recorded', `Code ${code}`, { code, actor: 'Workflow Engine', actor_type: 'system', metadata: Object.fromEntries(validation.map((g) => [g.key, g.status])) });
  if (quarantined) A('Code quarantined — validation failed', `Code ${code}`, { code, actor: 'Workflow Engine', actor_type: 'system', metadata: { detail: doc.detail ?? validation.find((g) => g.status === 'failed')?.detail ?? '' } });
});

if (!codes.length) return [{ json: { ok: false, reason: 'no_codes_proposed', input } }];

const model = {
  model_provider: ex.model?.provider ?? 'unknown', model_name: ex.model?.name ?? 'unknown', model_version: ex.model?.version ?? 'unknown',
  workflow_version: $env.WORKFLOW_VERSION ?? 'unversioned', ruleset_version: rulesetVersion,
};
const claim = {
  id: claimId, visitId: visit.visit_id, patientName: visit.patient.name ?? visit.patient.id, patientId: visit.patient.id,
  doctorId: visit.provider.id, doctorName: visit.provider.name ?? visit.provider.id,
  payer: pre.policy?.payer_name ?? 'Unknown payer', facility: visit.facility ?? 'Unknown facility',
  draftGeneratedAt: now, stage: 'doctor_review', status: 'pending_review', codes, noteText, noteSignedAt: visit.note.signed_at,
  regeneration: { state: 'idle', count: 0 }, model, reviewAgeHours: 0, versions: [],
};
return [{ json: {
  ok: true, mode: input.mode, run_id: runId, visit_id: visit.visit_id, claim,
  draft: { runId, codes, model, generatedAt: now },
  audit_rows: audit,
  quarantined: codes.filter((c) => c.quarantined).map((c) => ({ code: c.code })),
} }];

const r = $('Build draft claim').first().json;
const version = Number($input.first().json.version);
const label = `Draft v${version}`;
const now = new Date().toISOString();

r.audit_rows.forEach((a) => { a.version = label; });
r.audit_rows.push({
  ts: now, actor: 'Workflow Engine', actor_type: 'system', event: 'Draft claim created', entity: `Claim ${r.claim.id}`,
  claim_id: r.claim.id, visit_id: r.visit_id, patient_id: r.claim.patientId, code: null, previous_value: null, new_value: label,
  run_id: r.run_id, version: label,
  metadata: { codes: r.claim.codes.map((c) => c.code).join(', '), quarantined: String(r.quarantined.length), mode: r.mode },
});

r.claim.versions = [{
  label, number: version, kind: 'draft', createdAt: r.claim.draftGeneratedAt, createdBy: 'Coding Assistant', runId: r.run_id,
  codes: r.claim.codes.map((c) => ({ code: c.code, category: c.category, description: c.description, decision: 'pending' })),
}];
r.version = version;
r.version_label = label;
r.notifications = r.quarantined.map((q) => ({
  kind: 'quarantine', severity: 'warning', title: 'Code quarantined',
  message: `Code ${q.code} has been quarantined because required documentation evidence could not be verified.`,
  claim_id: r.claim.id, ref_id: q.code,
}));
return [{ json: r }];

const events = ($json.rows ?? []).map((r) => ({
  type: 'notification.created',
  notification: { id: `NTF-${r.id}`, kind: r.kind, severity: r.severity, title: r.title, message: r.message, claimId: r.claim_id ?? undefined, createdAt: r.created_at },
}));
return [{ json: { events } }];

// Every early exit lands here so the caller always gets { ok:false, reason, detail, retryable } and the audit log records why.
const j = $json;
const input = $('Execute Workflow Trigger').first().json;
let reason, detail, retryable;
if (j.gates) {
  reason = 'preflight_failed';
  const bad = Object.values(j.gates).filter((g) => g.status !== 'passed');
  detail = bad.map((g) => `${g.label}: ${g.status}${g.detail ? ` (${g.detail})` : ''}`).join('; ');
  retryable = bad.some((g) => g.status === 'unavailable');
} else if (j.reason === 'no_codes_proposed') {
  reason = 'no_codes_proposed';
  detail = 'The extraction produced no codes that could be proposed for this note.';
  retryable = false;
} else {
  reason = 'extraction_unavailable';
  detail = j.error?.message ?? 'The extraction service returned no usable result.';
  retryable = true;
}
return [{ json: {
  ok: false, reason, detail, retryable, visit_id: input.visit_id, run_id: input.run_id, mode: input.mode,
  audit_rows: [{ ts: new Date().toISOString(), actor: 'Workflow Engine', actor_type: 'system', event: 'Draft generation blocked', entity: `Visit ${input.visit_id}`,
    claim_id: input.claim_id ?? null, visit_id: input.visit_id, patient_id: null, code: null, previous_value: null, new_value: null, run_id: input.run_id, version: null,
    metadata: { reason, detail, retryable: String(retryable) } }],
} }];
